import{_ as t,a0 as d,w as p,s as r,ao as c,I as i,x as s,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用 rsync 複製大文件的一些誤解 | LCTT x X-CMD","titleTemplate":false,"description":"使用 rsync 複製大文件的一些誤解 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 rsync 複製大文件的一些誤解 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 rsync 複製大文件的一些誤解 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190916 Copying large files with Rsync, and some misconceptions","title":"使用 rsync 複製大文件的一些誤解","tag":"201910","desc":""},"relativePath":"201910/20190916 Copying large files with Rsync, and some misconceptions.md","filePath":"[post].md"}'),l={name:"201910/20190916 Copying large files with Rsync, and some misconceptions.md"};function g(y,e,f,h,u,m){const n=d("Link");return p(),r("div",null,[e[15]||(e[15]=c(`<h1 id="使用-rsync-複製大文件的一些誤解" tabindex="-1">使用 rsync 複製大文件的一些誤解 <a class="header-anchor" href="#使用-rsync-複製大文件的一些誤解" aria-label="Permalink to “使用 rsync 複製大文件的一些誤解”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/08/rsync-816x345.jpg" alt=""></p><p>有一種觀點認為，在 IT 行業工作的許多人經常從網絡帖子裏複製和粘貼。我們都幹過，複製粘貼本身不是問題。問題是當我們在不理解它們的情況下這樣幹。</p><p>幾年前，一個曾經在我團隊中工作的朋友需要將虛擬機模板從站點 A 複製到站點 B。他們無法理解為什麼複製的文件在站點 A 上為 10GB，但是在站點 B 上卻變為 100GB。</p><p>這位朋友認為 <code>rsync</code> 是一個神奇的工具，應該僅“同步”文件本身。但是，我們大多數人所忘記的是瞭解 <code>rsync</code> 的真正含義、用法，以及我認為最重要的是它原本是用來做什麼的。本文提供了有關 <code>rsync</code> 的更多信息，並解釋了那件事中發生了什麼。</p><h3 id="關於-rsync" tabindex="-1">關於 rsync <a class="header-anchor" href="#關於-rsync" aria-label="Permalink to “關於 rsync”">​</a></h3><p><code>rsync</code> 是由 Andrew Tridgell 和 Paul Mackerras 創建的工具，其動機是以下問題：</p><p>假設你有兩個文件，<code>file_A</code> 和 <code>file_B</code>。你希望將 <code>file_B</code> 更新為與 <code>file_A</code> 相同。顯而易見的方法是將 <code>file_A</code> 複製到 <code>file_B</code>。</p><p>現在，假設這兩個文件位於通過慢速通信鏈接（例如，撥號 IP 鏈接）連接的兩個不同的服務器上。如果<code>file_A</code> 大，將其複製到 <code>file_B</code> 將會很慢，有時甚至是不可能完成的。為了提高效率，你可以在發送前壓縮 <code>file_A</code>，但這通常只會獲得 2 到 4 倍的效率提升。</p><p>現在假設 <code>file_A</code> 和 <code>file_B</code> 非常相似，並且為了加快處理速度，你可以利用這種相似性。一種常見的方法是僅通過鏈接發送 <code>file_A</code> 和 <code>file_B</code> 之間的差異，然後使用這個差異列表在遠程端重建文件。</p><p>問題在於，用於在兩個文件之間創建一組差異的常規方法依賴於能夠讀取兩個文件。因此，它們要求鏈接的一端預先提供兩個文件。如果它們在同一台計算機上不是同時可用的，則無法使用這些算法。（一旦將文件複製過來，就不需要做對比差異了）。而這是 <code>rsync</code> 解決的問題。</p><p><code>rsync</code> 算法有效地計算源文件的哪些部分與現有目標文件的部分匹配。這樣，匹配的部分就不需要通過鏈接發送了；所需要的只是對目標文件部分的引用。只有源文件中不匹配的部分才需要發送。</p><p>然後，接收者可以使用對現有目標文件各個部分的引用和原始素材來構造源文件的副本。</p><p>另外，可以使用一系列常用壓縮算法中的任何一種來壓縮發送到接收器的數據，以進一步提高速度。</p><p>我們都知道，<code>rsync</code> 算法以一種漂亮的方式解決了這個問題。</p><p>在 <code>rsync</code> 的介紹之後，回到那件事！</p><h3 id="問題-1-自動精簡配置" tabindex="-1">問題 1：自動精簡配置 <a class="header-anchor" href="#問題-1-自動精簡配置" aria-label="Permalink to “問題 1：自動精簡配置”">​</a></h3><p>有兩件事可以幫助那個朋友瞭解正在發生的事情。</p><p>該文件在其他地方的大小變得越來越大的問題是由源系統上啓用了<ruby>自動精簡配置<rt>Thin Provisioning</rt></ruby>（TP）引起的，這是一種優化存儲區域網絡（SAN）或網絡連接存儲（NAS）中可用空間效率的方法。</p><p>由於啓用了 TP，源文件只有 10GB，並且在不使用任何其他配置的情況下使用 <code>rsync</code> 進行傳輸時，目標位置將接收到全部 100GB 的大小。<code>rsync</code> 無法自動完成該（TP）操作，必須對其進行配置。</p><p>進行此工作的選項是 <code>-S</code>（或 <code>–sparse</code>），它告訴 <code>rsync</code> 有效地處理稀疏文件。它會按照它説的做！它只會發送該稀疏數據，因此源和目標將有一個 10GB 的文件。</p><h3 id="問題-2-更新文件" tabindex="-1">問題 2：更新文件 <a class="header-anchor" href="#問題-2-更新文件" aria-label="Permalink to “問題 2：更新文件”">​</a></h3><p>當發送一個更新的文件時會出現第二個問題。現在目標僅接收 10GB 了，但始終傳輸的是整個文件（包含虛擬磁盤），即使只是在該虛擬磁盤上更改了一個配置文件。換句話説，只是該文件的一小部分發生了更改。</p><p>用於此傳輸的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -avS vmdk_file syncuser@host1:/destination</span></span></code></pre></div><p>同樣，瞭解 <code>rsync</code> 的工作方式也將有助於解決此問題。</p><p>上面是關於 <code>rsync</code> 的最大誤解。我們許多人認為 <code>rsync</code> 只會發送文件的增量更新，並且只會自動更新需要更新的內容。<strong>但這不是 <code>rsync</code> 的默認行為</strong>。</p><p>如手冊頁所述，<code>rsync</code> 的默認行為是在目標位置創建文件的新副本，並在傳輸完成後將其移動到正確的位置。</p><p>要更改 <code>rsync</code> 的默認行為，你必須設置以下標誌，然後 <code>rsync</code> 將僅發送增量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>--inplace               原地更新目標文件</span></span>
<span class="line"><span>--partial               保留部分傳輸的文件</span></span>
<span class="line"><span>--append                附加數據到更短的文件</span></span>
<span class="line"><span>--progress              在傳輸時顯示進度條</span></span></code></pre></div><p>因此，可以確切地執行我那個朋友想要的功能的完整命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -av --partial --inplace --append --progress vmdk_file syncuser@host1:/destination</span></span></code></pre></div><p>注意，出於兩個原因，這裏必須刪除稀疏選項 <code>-S</code>。首先是通過網絡發送文件時，不能同時使用 <code>–sparse</code> 和 <code>–inplace</code>。其次，當你以前使用過 <code>–sparse</code> 發送文件時，就無法再使用 <code>–inplace</code> 進行更新。請注意，低於 3.1.3 的 <code>rsync</code> 版本將拒絕 <code>–sparse</code> 和 <code>–inplace</code> 的組合。</p><p>因此，即使那個朋友最終通過網絡複製了 100GB，那也只需發生一次。以下所有更新僅複製差異，從而使複製非常高效。</p><hr>`,35)),i("p",null,[e[1]||(e[1]=s("via: ",-1)),o(n,{href:"https://fedoramagazine.org/copying-large-files-with-rsync-and-some-misconceptions/"},{default:a(()=>[...e[0]||(e[0]=[s("https://fedoramagazine.org/copying-large-files-with-rsync-and-some-misconceptions/",-1)])]),_:1})]),i("p",null,[e[6]||(e[6]=s("作者：",-1)),o(n,{href:"https://fedoramagazine.org/author/dabreu/"},{default:a(()=>[...e[2]||(e[2]=[s("Daniel Leite de Abreu",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),o(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[12]||(e[12]=s("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const C=t(l,[["render",g]]);export{T as __pageData,C as default};
